const $=s=>document.querySelector(s);
const icons={arrow:'M5 12h14m-5-5 5 5-5 5',back:'m14 6-6 6 6 6',home:'m3 10 9-7 9 7v10h-6v-6H9v6H3z',route:'M6 5a2 2 0 1 0 0 .1M18 19a2 2 0 1 0 0 .1M8 5h7a4 4 0 0 1 0 8H9a3 3 0 0 0 0 6h7',truck:'M2 6h13v12H2zM15 10h4l3 4v4h-7M5 18a2 2 0 1 0 4 0m8 0a2 2 0 1 0 4 0',box:'m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10M7 5l10 4',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 21a8 8 0 0 1 16 0',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',chart:'M4 20V9m8 11V4m8 16v-7'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.route}"/></svg>`;
let screen=0,selected='A',started=false,analysis=0,timer;
const values={name:'Entrega supermercado Oriente',goods:'Alimentos empacados',weight:'4800',length:'5.2',width:'2.1',height:'2.4',units:'36',load:'Carga seca',origin:'Centro de distribución Smart Route',originAddress:'Carrera 52 # 14-35, Medellín, Antioquia',destination:'Supermercado Oriente',destinationAddress:'Carrera 47 # 50-32, Rionegro, Antioquia',date:'2026-11-03',departure:'07:00',deadline:'09:30',email:'laura.gomez@transportesandina.com',password:'SmartRoute2026'};
const checks={remember:true,fragile:false,cold:false,toll:false,unpaved:true,main:true,freight:true,bridge:true,road:true};
const routes={A:{title:'Equilibrio inteligente',distance:'38,4',time:'1 h 06 min',cost:'87.500',arrival:'08:06 a. m.',margin:'1 h 24 min',risk:'Bajo'},B:{title:'Más rápida',distance:'35,2',time:'58 min',cost:'93.200',arrival:'07:58 a. m.',margin:'1 h 32 min',risk:'Medio'},C:{title:'Menor costo',distance:'43,8',time:'1 h 24 min',cost:'75.900',arrival:'08:24 a. m.',margin:'1 h 06 min',risk:'Bajo'}};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>`<div class="brand"><img src="assets/images/logo-smart-route.png" alt="Logo oficial Smart Route" width="448" height="282" decoding="async"></div>`;
function field(label,key,type='text',extra=''){return `<label class="field">${label}<input name="${key}" type="${type}" value="${esc(values[key])}" ${extra} oninput="values['${key}']=this.value; ${['weight','length','width','height'].includes(key)?'updateSummary()':''}"></label>`}
function check(label,key){return `<label class="check"><input type="checkbox" ${checks[key]?'checked':''} onchange="checks['${key}']=this.checked">${label}</label>`}
const badge=(s,c='')=>`<span class="badge ${c}">${s}</span>`;
const detail=(k,v)=>`<div class="detail"><span>${k}</span><b>${v}</b></div>`;
const info=(title,text,warn=false)=>`<div class="info ${warn?'warning':''}"><strong>${icon(warn?'shield':'spark')} ${title}</strong><p>${text}</p></div>`;
function steps(n){return `<div class="steps">${['Carga','Vehículo','Entrega','Optimización'].map((x,i)=>`<div class="step ${i===n?'active':i<n?'done':''}">${i<n?'✓':i+1} · ${x}</div>`).join('')}</div>`}
const cta=(label,action,disabled=false)=>`<div class="cta"><button class="primary" onclick="${action}" ${disabled?'disabled':''}>${label}${icon('arrow')}</button></div>`;
function map(mode='all'){let grid='';for(let i=0;i<18;i++){const x=i*29;grid+=`<path d="M${x-80} 0l70 220M0 ${i*22}l430 -40"/>`;}return `<div class="map ${mode==='analysis'?'scan':''}"><span class="maplabel">${mode==='final'?'RUTA '+selected+' · VALIDADA':'VALLE DE ABURRÁ · ORIENTE'}</span><svg viewBox="0 0 350 220" role="img" aria-label="Mapa de demostración: Medellín a Rionegro"><rect width="350" height="220" fill="#17271f"/><path d="M200 0 170 40 200 80 176 120 230 180 210 220H350V0" fill="#203126"/><g stroke="#32453a" stroke-width="1" fill="none">${grid}</g><path d="M91 0 102 45 81 88 105 133 95 179 120 220" stroke="#254e53" stroke-width="7" fill="none"/><g stroke="#617063" stroke-width="3" fill="none"><path d="M20 210 74 155 106 118 140 70 144 0"/><path d="M0 108 90 118 156 99 213 123 290 96 350 112"/><path d="M102 220 162 183 215 177 270 132 350 160"/></g>${mode!=='final'?'<path d="M98 132 140 168 208 187 259 159 290 111" stroke="#7b888b" fill="none" stroke-width="3"/><path d="M98 132 141 107 183 87 233 85 290 111" stroke="#a8c0d3" fill="none" stroke-width="3"/><path d="M183 87 211 86" stroke="#f5b942" stroke-width="4" fill="none"/>':''}<path d="${mode==='final'&&selected==='C'?'M98 132 140 168 208 187 259 159 290 111':'M98 132 132 135 162 119 184 132 219 125 249 133 270 117 290 111'}" stroke="#081f17" fill="none" stroke-width="10"/><path d="${mode==='final'&&selected==='C'?'M98 132 140 168 208 187 259 159 290 111':'M98 132 132 135 162 119 184 132 219 125 249 133 270 117 290 111'}" stroke="${mode==='final'&&selected!=='A'?'#a8c0d3':'#00efac'}" fill="none" stroke-width="4" ${mode==='pre'?'stroke-dasharray="5 5"':''}/><circle cx="98" cy="132" r="7" fill="#00ffbb" stroke="#0c2018" stroke-width="3"/><circle cx="290" cy="111" r="7" fill="white" stroke="#0c2018" stroke-width="3"/><text x="48" y="153" class="city">Medellín</text><text x="267" y="94" class="city">Rionegro</text><text x="65" y="55">Bello</text><text x="40" y="193">Itagüí</text><text x="177" y="61">Santa Elena</text><text x="210" y="159">Aeropuerto JMC</text><rect x="169" y="102" width="42" height="17" rx="4" fill="#0b1913"/><text x="174" y="114" fill="#00ffbb">${mode==='final'?routes[selected].time:'1 h 06'}</text></svg><span class="mapkey">${mode==='all'?'● A · Recomendada &nbsp; ● B &nbsp; ● C':'● Origen &nbsp; ○ Destino'} · Demo</span></div>`}
function nav(){const items=[['home','Inicio',1],['route','Planificar',2],['box','Operaciones',-1],['truck','Vehículos',3],['user','Perfil',-2]];return `<nav class="bottom" aria-label="Navegación principal">${items.map(([i,l,n])=>`<button class="${(screen===1&&n===1)||(screen>=2&&screen<=6&&n===2)?'active':''}" onclick="${n===-1?'operations()':n===-2?'profile()':`go(${n})`}">${icon(i)}${l}</button>`).join('')}</nav>`}
function render(){clearInterval(timer);$('#app').innerHTML=`<div class="status"><span>9:41</span><span>▴▴▴ &nbsp; Wi-Fi &nbsp; ▰</span></div>${screen?`<header class="appbar">${screen>1?`<button class="iconbtn" aria-label="Anterior" onclick="go(${screen===7?6:screen-1})">${icon('back')}</button>`:brand()}${screen>1?brand():''}<button class="iconbtn" aria-label="Notificaciones" onclick="notice()">${icon('bell')}</button></header>`:''}<main class="${screen===0?'login':''}" id="main">${[login,dashboard,cargo,vehicles,delivery,analyze,compare,confirmation][screen]()}</main>${screen?nav():''}`;if(screen===5)startAnalysis();}
function go(n){screen=n;if(n===5)analysis=0;render();window.scrollTo({top:0,behavior:'instant'});}
function login(){return `${brand()}<div class="eyebrow" style="margin-top:30px">Inteligencia que mueve tu negocio</div><h1>Cada carga.<br>La ruta <em>correcta.</em></h1><p class="subtitle">Rutas inteligentes, decisiones eficientes.</p>${map('pre')}<p>Planea rutas teniendo en cuenta tu vehículo, tu carga y las restricciones reales de circulación.</p><form onsubmit="event.preventDefault();loginSubmit(this)">${field('Correo electrónico','email','email','required autocomplete="username"')}${field('Contraseña','password','password','required minlength="6" autocomplete="current-password"')}<div class="row">${check('Recordarme','remember')}<button type="button" class="textbtn" onclick="modal('Recupera tu acceso','En este prototipo no se envían correos. Solicita el restablecimiento a la persona administradora de Transportes Andina S.A.S.')">¿Olvidaste tu contraseña?</button></div><button class="primary" type="submit" id="login-button">Iniciar sesión ${icon('arrow')}</button></form><div class="login-footer">¿Tu empresa aún no tiene una cuenta?<br><button class="textbtn" onclick="modal('Solicitar acceso','Demo para Pymes transportistas. Presenta el nombre de tu empresa, tamaño de la flota y correo de contacto al equipo comercial de Smart Route.')">Solicitar acceso</button></div><div class="footerline">PLANEACIÓN SEGURA · CONTROL LOGÍSTICO</div>`}
function loginSubmit(form){if(!form.reportValidity())return;$('#login-button').disabled=true;$('#login-button').innerHTML='<span class="spinner"></span> Ingresando…';setTimeout(()=>go(1),650)}
function dashboard(){return `<div class="row"><p class="eyebrow">Martes, 03 nov 2026</p><div class="avatar">LG</div></div><h1>Centro de<br>operaciones</h1><p class="subtitle">Supervisa tus rutas, entregas y alertas logísticas desde un solo lugar.</p><p class="small">Transportes Andina S.A.S. · Hola, Laura</p><div class="grid stats">${[['12','rutas programadas','route'],['8','rutas en curso','truck'],['3','entregas completadas','check'],['1','alerta de restricción','shield']].map(([v,t,i])=>`<div class="stat">${icon(i)}<strong>${v}</strong><span>${t}</span></div>`).join('')}</div>${cta('Planificar nueva ruta','go(2)')}<div class="row sectionhead"><h2>Tu operación, en movimiento</h2>${badge('8 activas')}</div>${map()}<div class="card"><div class="row"><div><span class="small">Cumplimiento estimado</span><h1 style="margin:8px 0">87 <span style="font-size:16px;color:#85978f">%</span></h1></div><div class="bar-chart" aria-label="Cumplimiento de entregas de los últimos siete días">${[38,55,45,72,65,81,87].map(v=>`<i style="height:${v}%"></i>`).join('')}</div></div><div class="progress"><i style="width:87%"></i></div><span class="small" style="color:#71dec0">↗ 42 min ahorrados hoy</span></div><div class="row sectionhead"><h2>Operaciones recientes</h2><button class="textbtn" onclick="operations()">Ver todas</button></div>${[['1048','Medellín → Rionegro','En ruta',''],['1047','Bello → Itagüí','Completada',''],['1046','Medellín → Caldas','Advertencia','warn']].map(([n,r,s,c])=>`<button class="operation" onclick="modal('SR-2026-${n}','${r} · ${s}. ${n==='1046'?'Verificar horario permitido para circulación de carga antes de salir.':'La operación tiene seguimiento activo en la simulación.'}')"><span class="opicon">${icon('truck')}</span><span style="flex:1"><strong>SR-2026-${n}</strong><small>${r}</small></span>${badge(s,c)}</button>`).join('')}`}
function cargo(){return `${steps(0)}<p class="eyebrow">Paso 01 / 04</p><h1>Nueva operación<br>logística</h1><p class="subtitle">Cuéntanos qué transportas. Validaremos que tu carga viaje en el vehículo adecuado.</p>${field('Nombre de la operación','name','text','required')}${field('Tipo de mercancía','goods')}${field('Peso total · kg','weight','number','min="1" inputmode="decimal"')}${field('Largo de la carga · m','length','number','min="0.1" step="0.1" inputmode="decimal"')}${field('Ancho de la carga · m','width','number','min="0.1" step="0.1" inputmode="decimal"')}${field('Alto de la carga · m','height','number','min="0.1" step="0.1" inputmode="decimal"')}${field('Cantidad de unidades · pallets','units','number','min="1" inputmode="numeric"')}<label class="field">Tipo de carga<select onchange="values.load=this.value;updateSummary()"><option ${values.load==='Carga seca'?'selected':''}>Carga seca</option><option ${values.load==='Carga refrigerada'?'selected':''}>Carga refrigerada</option></select></label>${check('Mercancía frágil','fragile')}${check('Requiere control de temperatura','cold')}<div class="card"><h2>Resumen de carga</h2><div id="load-summary">${loadSummary()}</div><p class="small">Verifica unidades y dimensiones antes de continuar.</p></div>${cta('Continuar con vehículo','validateCargo()')}<button class="secondary" onclick="go(1)">Cancelar</button>`}
function loadSummary(){return detail('Peso',(Number(values.weight)/1000).toLocaleString('es-CO')+' t')+detail('Volumen estimado',(Number(values.length)*Number(values.width)*Number(values.height)).toLocaleString('es-CO',{maximumFractionDigits:1})+' m³')+detail('Tipo',esc(values.load))+detail('Riesgo','Bajo')}
function updateSummary(){if($('#load-summary'))$('#load-summary').innerHTML=loadSummary()}
function validCargo(){return Number(values.weight)>0&&Number(values.weight)<=5500&&Number(values.length)>0&&Number(values.length)<=5.2&&Number(values.width)>0&&Number(values.width)<=2.1&&Number(values.height)>0&&Number(values.height)<=2.4&&!checks.cold&&values.load==='Carga seca'}
function validateCargo(){if(!values.name.trim()||!validCargo()){modal('Revisa la carga','Esta demostración valida carga seca de hasta 5.500 kg y 5,2 × 2,1 × 2,4 m. El vehículo disponible no tiene refrigeración. Ajusta los datos para continuar.');return}go(3)}
function vehicles(){return `${steps(1)}<p class="eyebrow">Paso 02 / 04</p><h1>El vehículo<br>adecuado</h1><p class="subtitle">La ruta debe adaptarse a tu vehículo. Comparamos capacidad, dimensiones y disponibilidad.</p><button class="vehicle selected" onclick="toast('Chevrolet NPR · JKT-482 seleccionado')" aria-pressed="true"><div class="row"><h3>Chevrolet NPR</h3>${badge('✓ Recomendado')}</div><span class="small">JKT-482 · Disponible</span><div class="truck-art"><svg viewBox="0 0 160 80" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 15h87v44H12zM99 30h27l19 18v11H99z" fill="#31403e"/><path d="M108 34h15l12 12h-27z" fill="#73918a"/><path d="M17 23h75M17 31h75M17 39h75" stroke="#4b615a"/><circle cx="38" cy="62" r="10" fill="#0b1314"/><circle cx="122" cy="62" r="10" fill="#0b1314"/><circle cx="38" cy="62" r="4"/><circle cx="122" cy="62" r="4"/></svg></div>${detail('Capacidad','5,5 t')}${detail('Alto total cargado','3,15 m')}${detail('Ancho exterior · Largo exterior','2,35 m · 6,20 m')}<div class="progress"><i style="width:96%"></i></div><div class="row"><span class="small">Compatibilidad con la carga</span><b style="color:#00ffbb;font-size:12px">96 %</b></div></button><button class="vehicle" disabled><div class="row"><h3>Hino 300</h3>${badge('Capacidad insuficiente','warn')}</div><span class="small">LMP-735 · Disponible</span>${detail('Capacidad','4,5 t')}${detail('Carga registrada',(Number(values.weight)/1000).toLocaleString('es-CO')+' t')}</button><button class="vehicle" disabled><div class="row"><h3>Foton Aumark</h3>${badge('No disponible','red')}</div><span class="small">TRC-901 · En mantenimiento</span>${detail('Capacidad','6,0 t')}</button>${info('Validación Smart Route','El vehículo JKT-482 es compatible con el peso y las dimensiones registradas. Medidas útiles verificadas: 5,2 × 2,1 × 2,4 m.')}${cta('Continuar con entrega','go(4)',!validCargo())}`}
function delivery(){return `${steps(2)}<p class="eyebrow">Paso 03 / 04</p><h1>Configura<br>la entrega</h1><p class="subtitle">Define dónde y cuándo. Nosotros contrastamos las condiciones del recorrido.</p><div class="card"><h2>01 · Origen</h2>${field('Centro de distribución','origin')}${field('Dirección de recogida','originAddress')}</div><div class="card"><h2>02 · Destino</h2>${field('Punto de entrega','destination')}${field('Dirección de entrega','destinationAddress')}</div>${map('pre')}<p class="map-caption">Representación de demostración · No apta para navegación</p>${field('Fecha de salida','date','date')}${field('Hora estimada de salida','departure','time')}${field('Entrega máxima','deadline','time')}<h2 class="sectionhead">Preferencias del recorrido</h2>${[['Evitar peajes','toll'],['Evitar vías sin pavimentar','unpaved'],['Priorizar vías principales','main'],['Considerar restricciones para carga','freight'],['Considerar altura de puentes','bridge'],['Considerar ancho mínimo de vía','road']].map(([l,k])=>`<label class="switchrow">${l}<input type="checkbox" role="switch" ${checks[k]?'checked':''} onchange="checks['${k}']=this.checked"></label>`).join('')}${info('Restricciones reales, decisiones claras','Smart Route detectará automáticamente restricciones que puedan afectar al vehículo seleccionado.')}${cta('Analizar rutas con IA','validateDelivery()')}`}
function validateDelivery(){if(values.date!=='2026-11-03'||values.departure!=='07:00'||values.deadline!=='09:30'||checks.toll||!checks.unpaved||!checks.main||!checks.freight||!checks.bridge||!checks.road||values.originAddress!=='Carrera 52 # 14-35, Medellín, Antioquia'||values.destinationAddress!=='Carrera 47 # 50-32, Rionegro, Antioquia'){modal('Escenario de demostración','Las tres rutas precalculadas corresponden a Medellín → Rionegro, el 03/11/2026 de 07:00 a 09:30, con un peaje y todas las validaciones activas. Puedes restaurar ese escenario para continuar.<br><button class="secondary" onclick="restoreDelivery()">Restaurar escenario y analizar</button>');return}go(5)}
function restoreDelivery(){Object.assign(values,{date:'2026-11-03',departure:'07:00',deadline:'09:30',originAddress:'Carrera 52 # 14-35, Medellín, Antioquia',destinationAddress:'Carrera 47 # 50-32, Rionegro, Antioquia'});Object.assign(checks,{toll:false,unpaved:true,main:true,freight:true,bridge:true,road:true});$('dialog').close();go(5)}
const analysisTexts=['Capacidad del vehículo validada','Dimensiones de carga validadas','Restricciones de circulación verificadas','Alturas de puentes verificadas','Ancho mínimo de vías verificado','Ventana de entrega analizada','Costos estimados calculados'];
function analyze(){return `${steps(3)}<p class="eyebrow">Motor de planeación · IA</p><h1 id="analysis-title">Analizando las<br>mejores rutas</h1><p class="subtitle">Estamos contrastando la carga, el vehículo, las restricciones viales y el horario de entrega.</p><div id="analysis-map" class="analyzing">${map('analysis')}</div><div class="row"><span class="small" id="analysis-caption">Contrastando condiciones…</span><b id="analysis-percent" style="font-size:12px;color:#00ffbb">0 %</b></div><div class="progress"><i id="analysis-progress" style="width:0%"></i></div><ul class="analysis-list">${analysisTexts.map((t,i)=>`<li id="analysis-${i}"><i>·</i>${t}</li>`).join('')}</ul><div id="analysis-result" hidden><div class="card">${detail('Rutas viables encontradas','3')}${detail('Restricciones que descartaron alternativas','2')}${detail('Ruta recomendada por Smart Route','1')}</div>${info('Altura incompatible detectada','Se descartó una alternativa por una restricción de altura de 3,00 m. El vehículo seleccionado alcanza 3,15 m.',true)}<p class="small">Simulación con reglas y datos locales. La validación operativa final corresponde al equipo logístico.</p></div>${cta('Analizando…','go(6)',true)}`}
function startAnalysis(){timer=setInterval(()=>{analysis++;const li=$('#analysis-'+(analysis-1));if(li){li.classList.add('complete');li.querySelector('i').textContent='✓'}$('#analysis-percent').textContent=Math.round(analysis/7*100)+' %';$('#analysis-progress').style.width=analysis/7*100+'%';if(analysis===7){clearInterval(timer);$('#analysis-result').hidden=false;$('#analysis-map').classList.remove('analyzing');$('#analysis-title').innerHTML='Encontramos<br>tu mejor ruta';$('#analysis-caption').textContent='Análisis completado';const b=$('#main .cta button');b.disabled=false;b.innerHTML='Ver rutas recomendadas '+icon('arrow');}},430)}
function routeCard(id){const r=routes[id];return `<label class="route ${selected===id?'selected':''}" style="display:block"><div class="row"><h3>Ruta ${id} · ${r.title}</h3><input type="radio" name="route" value="${id}" ${selected===id?'checked':''} onchange="selectRoute('${id}')"></div>${id==='A'?badge('Recomendada por Smart Route'):id==='B'?badge('1 advertencia','warn'):badge('Menor costo','gray')}<div class="metrics"><div><strong>${r.distance}</strong><small>kilómetros</small></div><div><strong>${r.time}</strong><small>tiempo estimado</small></div></div><div class="row"><span class="cost">$${r.cost} <span class="small">COP</span></span>${badge('Riesgo '+r.risk,id==='B'?'warn':'')}</div>${id==='A'?detail('Peajes · Cumplimiento · Restricciones','1 · 98 % · 0 críticas'):''}<p>${id==='A'?'Equilibra tiempo, costo, seguridad y compatibilidad con el vehículo.':id==='B'?'Más rápida, pero atraviesa un corredor con restricción horaria para carga pesada. Requiere revisar el horario autorizado antes de salir.':'Reduce costos, pero disminuye el margen disponible para cumplir la hora máxima de entrega.'}</p></label>`}
function compare(){return `<p class="eyebrow">03 alternativas · Una decisión informada</p><h1>Rutas<br>recomendadas</h1><p class="subtitle">Más que llegar rápido: llegar por una vía compatible con tu operación.</p>${map()}<p class="map-caption">Verde: A · Azul grisáceo: B · Gris: C · Amarillo: restricción</p>${['A','B','C'].map(routeCard).join('')}${info('¿Por qué recomendamos la Ruta A?','Evita restricciones de altura y circulación, mantiene un margen de 1 h 24 min frente a la hora máxima de entrega y presenta el mejor balance entre costo y seguridad.')}${selected==='B'?info('Revisión de horario pendiente','Esta alternativa tiene una advertencia de circulación. En esta demo no puede confirmarse sin validación del corredor.',true):''}${cta('Seleccionar Ruta '+selected,'confirmRoute()',selected==='B')}`}
function selectRoute(id){const y=scrollY;selected=id;render();window.scrollTo(0,y)}
function confirmRoute(){started=false;go(7)}
function confirmation(){const r=routes[selected];return `<div class="success">${icon(started?'truck':'check')}</div><p class="eyebrow">Operación SR-2026-1049</p><h1>${started?'Tu operación<br>está en ruta':'Ruta lista<br>para iniciar'}</h1>${badge(started?'● En ruta':'✓ Ruta optimizada')}<div class="card"><h2>${esc(values.name)}</h2>${detail('Vehículo','Chevrolet NPR · JKT-482')}${detail('Conductor','Carlos Ramírez')}${detail('Origen → Destino','Medellín → Rionegro')}${detail('Salida','03 nov 2026 · 07:00 a. m.')}${detail('Llegada estimada',r.arrival)}${detail('Hora máxima','09:30 a. m.')}</div>${map('final')}<div class="grid stats">${[[r.distance+' km','Distancia'],[r.time,'Tiempo estimado'],['$'+r.cost,'Costo estimado · COP'],[r.margin,'Margen de entrega']].map(([v,l])=>`<div class="stat"><strong style="font-size:20px">${v}</strong><span>${l}</span></div>`).join('')}</div><div class="card">${detail('Riesgo',r.risk)}${detail('Compatibilidad con la vía','100 %')}${detail('Ajuste recomendado del vehículo','96 %')}</div>${info('Smart Route evitó','✓ 1 vía incompatible con la altura del vehículo<br>✓ 1 corredor con restricción horaria')}<div class="card"><h2>Beneficio estimado</h2><p><b style="color:#00ffbb">${selected==='A'?'18 min':'Menor costo'}</b> ${selected==='A'?'de ahorro frente a una ruta convencional no validada':'para una entrega con margen de 1 h 06 min'}</p><p><b style="color:#00ffbb">$${selected==='A'?'5.700':'17.300'} COP</b> de ahorro estimado frente a la alternativa más costosa ($93.200 COP).</p></div>${cta(started?'Ruta iniciada · En seguimiento':'Iniciar ruta','startRoute()',started)}<button class="secondary" onclick="downloadSummary()">${icon('download')} Descargar resumen</button><button class="textbtn" style="width:100%" onclick="go(1)">Volver al dashboard</button><p class="small" style="text-align:center">Prototipo académico · Datos y mapas de demostración</p>`}
function startRoute(){started=true;render();toast('Ruta iniciada. Carlos Ramírez está en camino.')}
function downloadSummary(){const r=routes[selected];const text=`SMART ROUTE — RESUMEN DE OPERACIÓN\nDatos simulados · No apto para navegación\n\nSR-2026-1049 · ${values.name}\nEmpresa: Transportes Andina S.A.S.\nConductor: Carlos Ramírez\nVehículo: Chevrolet NPR · JKT-482\nCarga: ${values.weight} kg · ${values.length} × ${values.width} × ${values.height} m\nOrigen: ${values.origin} · ${values.originAddress}\nDestino: ${values.destination} · ${values.destinationAddress}\nSalida: 03/11/2026 · 07:00 a. m.\nRuta: ${selected}\nLlegada: ${r.arrival}\nEntrega máxima: 09:30 a. m.\nDistancia: ${r.distance} km\nTiempo: ${r.time}\nCosto: $${r.cost} COP\nMargen: ${r.margin}\nEstado: ${started?'En ruta':'Ruta optimizada'}\nRestricciones evitadas: altura de 3,00 m y corredor con restricción horaria.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='smart-route-SR-2026-1049.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Resumen descargado')}
function modal(title,text){$('#dialog-content').innerHTML=`<h2>${title}</h2><p>${text}</p>`;$('dialog').showModal()}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function notice(){modal('1 alerta de restricción','SR-2026-1046 · Medellín → Caldas. Verifica el horario permitido para vehículos de carga antes de iniciar el recorrido.')}
function operations(){modal('Operaciones de hoy','SR-2026-1048 · Medellín → Rionegro · En ruta<br>SR-2026-1047 · Bello → Itagüí · Completada<br>SR-2026-1046 · Medellín → Caldas · Advertencia'+(screen===7?'<br>SR-2026-1049 · Medellín → Rionegro · '+(started?'En ruta':'Programada'):''))}
function profile(){modal('Laura Gómez',brand()+'Coordinadora logística<br>Transportes Andina S.A.S.<br><br>Smart Route · Rutas inteligentes, decisiones eficientes.<br><button class="secondary" onclick="document.querySelector(\'dialog\').close();go(0)">Cerrar sesión</button>')}
render();
